reference_solution:
def province_count(is_connected):
    seen = set()
    def visit(city):
        seen.add(city)
        for neighbor, connected in enumerate(is_connected[city]):
            if connected and neighbor not in seen:
                visit(neighbor)
    answer = 0
    for city in range(len(is_connected)):
        if city not in seen:
            answer += 1
            visit(city)
    return answer

